  qrPage=function(){const scanner=scannerPanel();if(platform.user?.role==='Operator')return `${intro(L().mobile,U().scanNow)}${scanner}`;let html=originalQr();platform.locations.forEach(item=>{html=html.replaceAll(item.name,catalogLabel(item.name)).replaceAll(item.org,catalogLabel(item.org))});html=html.replaceAll('Coffee Жинау орны',catalogLabel('Coffee Point')).replaceAll('Coffee Место сбора',catalogLabel('Coffee Point'));return html.replace('<div class="smart-qr-intro">',`${scanner}<div class="smart-qr-intro">`)};

  const originalAnalytics=analyticsV2;
  analyticsV2=function(){const approved=state.reports.filter(item=>item.status==='approved');const orgs=platform.user?.role==='Operator'?[...new Set(state.reports.map(item=>item.org))]:platform.organizations.map(item=>item.name);const total=org=>approved.filter(item=>!org||item.org===org).reduce((sum,item)=>sum+item.kg,0);const a=platform.compareOrgA||orgs[0]||'',b=platform.compareOrgB||orgs[1]||orgs[0]||'';const monthly=Array.from({length:3},(_,offset)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-offset);const key=d.toISOString().slice(0,7);return{key,value:approved.filter(item=>item.date.startsWith(key)).reduce((sum,item)=>sum+item.kg,0)}}).reverse();const enough=monthly.every(item=>item.value>0),forecast=enough?Math.max(0,monthly.at(-1).value+(monthly.at(-1).value-monthly[0].value)/2):null;const toolbar=`<section class="card analytics-compare"><div class="card-head"><h3>${U().compare}</h3><button class="btn btn-soft" id="downloadTrendPng">⇩ ${U().downloadChart}</button></div><div class="compare-controls"><select id="compareOrgA">${optionList(orgs,a,'')}</select><strong>${total(a).toFixed(1)} kg</strong><span>vs</span><select id="compareOrgB">${optionList(orgs,b,'')}</select><strong>${total(b).toFixed(1)} kg</strong><div class="forecast-box"><small>${U().forecast}</small><b>${forecast===null?U().insufficient:`${forecast.toFixed(1)} kg`}</b></div></div></section>`;return originalAnalytics()+toolbar};

