  async function saveManager(form,path,transform=value=>value){if(!form.reportValidity())return;const input=transform(Object.fromEntries(new FormData(form)));const button=form.querySelector('button');await runBusy(button,async()=>{try{const payload=await api(path,{method:'POST',body:JSON.stringify(input)});acceptServer(payload);render();toast(U().save)}catch{toast(P().serverError)}})}
  function parseLocationCode(raw){const value=String(raw||'').trim();if(!value)return {error:U().unknownPoint};if(/^https?:\/\//i.test(value)){try{const url=new URL(value);if(url.origin!==location.origin||url.pathname!==location.pathname)return {error:U().invalidQr};const code=url.searchParams.get('location');return code?{code}:{error:U().invalidQr}}catch{return {error:U().invalidQr}}}return /^[a-z0-9-]{3,24}$/i.test(value)?{code:value}:{error:U().invalidQr}}
  function scanFeedback(){try{navigator.vibrate?.(80);const Audio=window.AudioContext||window.webkitAudioContext;if(Audio){const context=new Audio(),oscillator=context.createOscillator(),gain=context.createGain();oscillator.frequency.value=880;gain.gain.value=.035;oscillator.connect(gain);gain.connect(context.destination);oscillator.start();oscillator.stop(context.currentTime+.09)}}catch{}}
  function applyLocationCode(raw){const parsed=parseLocationCode(raw),message=document.getElementById('qrScannerMessage');if(parsed.error){if(message)message.textContent=parsed.error;toast(parsed.error);return false}const point=platform.locations.find(item=>item.id.toLowerCase()===parsed.code.toLowerCase());if(!point){if(message)message.textContent=U().unknownPoint;toast(U().unknownPoint);return false}if(point.active===false){if(message)message.textContent=U().inactiveQr;toast(U().inactiveQr);return false}if(platform.user?.role==='Operator'&&point.org!==platform.user.org){if(message)message.textContent=U().wrongOrg;toast(U().wrongOrg);return false}scanFeedback();stopScanner();platform.qrLocationId=point.id;platform.formOrg=point.org;rememberOrganization(point.org);platform.quickMode=true;state.page='forms';render();toast(`${U().scanSuccess}: ${catalogLabel(point.name)}`);return true}
