  async function startScanner(){const video=document.getElementById('qrVideo'),message=document.getElementById('qrScannerMessage'),start=document.getElementById('startQrCamera'),retry=document.getElementById('retryQrCamera');if(!video||!message)return;if(retry)retry.hidden=true;message.textContent=U().openingCamera;if(start){start.disabled=true;start.setAttribute('aria-busy','true')}const fail=text=>{stopScanner();scannerControls(false);if(start){start.disabled=false;start.removeAttribute('aria-busy');start.hidden=true}if(retry)retry.hidden=false;message.textContent=text;const fallback=document.querySelector('.qr-manual-fallback');if(fallback)fallback.open=true};if(!navigator.mediaDevices?.getUserMedia){fail(U().cameraError);return}try{stopScanner();const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:platform.qrFacing||'environment'}}});platform.qrStream=stream;const track=stream.getVideoTracks()[0];video.srcObject=stream;await video.play();if(start){start.disabled=false;start.removeAttribute('aria-busy')}scannerControls(true,track);if(retry)retry.hidden=true;message.textContent=U().scanActive;const detector='BarcodeDetector'in window?new BarcodeDetector({formats:['qr_code']}):null,canvas=document.createElement('canvas'),context=canvas.getContext('2d',{willReadFrequently:true});let frames=0;const scan=async()=>{if(!video.srcObject)return;let value='';if(video.videoWidth){canvas.width=video.videoWidth;canvas.height=video.videoHeight;context.drawImage(video,0,0);const image=context.getImageData(0,0,canvas.width,canvas.height);if(detector){const codes=await detector.detect(video).catch(()=>[]);value=codes[0]?.rawValue||''}else if(window.jsQR)value=window.jsQR(image.data,image.width,image.height,{inversionAttempts:'attemptBoth'})?.data||'';if(++frames%30===0&&!value){let light=0;for(let i=0;i<image.data.length;i+=160)light+=(image.data[i]+image.data[i+1]+image.data[i+2])/3;light/=Math.max(1,image.data.length/160);message.textContent=light<48?U().lowLight:U().scanActive}}if(value){const normalized=String(value).trim(),now=Date.now();if(normalized===platform.qrLastValue&&now-Number(platform.qrLastTime||0)<3000){platform.qrAnimation=requestAnimationFrame(scan);return}platform.qrLastValue=normalized;platform.qrLastTime=now;if(applyLocationCode(value))return;message.textContent=message.textContent||U().scanActive}platform.qrAnimation=requestAnimationFrame(scan)};scan()}catch(error){fail(error?.name==='NotAllowedError'?U().permissionDenied:U().cameraError)}}
  async function compressPhoto(file){const load=async()=>{if('createImageBitmap'in window)return createImageBitmap(file);return new Promise((resolve,reject)=>{const image=new Image(),url=URL.createObjectURL(file);image.onload=()=>{URL.revokeObjectURL(url);resolve(image)};image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('IMAGE_LOAD_FAILED'))};image.src=url})};const bitmap=await load(),max=1280,ratio=Math.min(1,max/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);if(bitmap.close)bitmap.close();return canvas.toDataURL('image/jpeg',.78)}
  function downloadTrend(){const svg=document.querySelector('.chart-wrap svg');if(!svg){toast(P().noRecords);return}const source=new XMLSerializer().serializeToString(svg),canvas=document.createElement('canvas');canvas.width=1400;canvas.height=480;const image=new Image();image.onload=()=>{const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);const link=document.createElement('a');link.download=`ecofood-trend-${new Date().toISOString().slice(0,10)}.png`;link.href=canvas.toDataURL('image/png');link.click();URL.revokeObjectURL(image.src)};image.src=URL.createObjectURL(new Blob([source],{type:'image/svg+xml'}))}

