    const photo=document.getElementById('platformPhoto');if(photo)photo.onchange=async()=>{const file=photo.files[0];if(!file)return;if(file.size>6_000_000){toast(photoLimitMessage());photo.value='';return}try{platform.photoData=await compressPhoto(file);platform.photoSuggestion=await window.EcoFoodSmartInput.classifyFile(file);render()}catch{toast(P().serverError)}};
